import { readFileSync } from "node:fs"
import { join } from "node:path"

export const dynamic = "force-static"

/** /theme/tokens.md: the token reference, generated by scripts/content.ts (not committed). */
export function GET() {
  const text = readFileSync(join(process.cwd(), "content/generated/tokens.md"), "utf8")
  return new Response(text, { headers: { "content-type": "text/markdown; charset=utf-8" } })
}
